import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { Html5QrcodeScanner } from 'html5-qrcode';
import { FiArrowLeft, FiCamera, FiUpload } from 'react-icons/fi';
import toast from 'react-hot-toast';

const ScanQR = () => {
  const [isScanning, setIsScanning] = useState(false);
  const [scannedData, setScannedData] = useState(null);
  const [error, setError] = useState(null);
  const scannerRef = useRef(null);
  const navigate = useNavigate();

  useEffect(() => {
    return () => {
      // Cleanup scanner on unmount
      if (scannerRef.current) {
        scannerRef.current.clear();
      }
    };
  }, []);

  const startScanning = () => {
    setIsScanning(true);
    setError(null);
    setScannedData(null);

    const scanner = new Html5QrcodeScanner(
      'qr-reader',
      {
        fps: 10,
        qrbox: { width: 250, height: 250 },
        aspectRatio: 1.0,
        showTorchButtonIfSupported: true,
        showZoomSliderIfSupported: true,
        defaultZoomValueIfSupported: 2,
      },
      false
    );

    scannerRef.current = scanner;

    scanner.render(
      (decodedText, decodedResult) => {
        // Success callback
        handleScanSuccess(decodedText);
        scanner.clear();
        setIsScanning(false);
      },
      (error) => {
        // Error callback (optional)
        console.warn('QR scan error:', error);
      }
    );
  };

  const stopScanning = () => {
    if (scannerRef.current) {
      scannerRef.current.clear();
      scannerRef.current = null;
    }
    setIsScanning(false);
  };

  const handleScanSuccess = (decodedText) => {
    try {
      const parsedData = JSON.parse(decodedText);

      // Validate QR code structure
      if (!parsedData.userId || !parsedData.type) {
        throw new Error('Invalid QR code format');
      }

      setScannedData(parsedData);
      toast.success('QR code scanned successfully!');
    } catch (error) {
      console.error('QR parsing error:', error);
      setError('Invalid QR code. Please scan a valid Digital Wallet QR code.');
      toast.error('Invalid QR code format');
    }
  };

  const handleFileUpload = (event) => {
    const file = event.target.files[0];
    if (!file) return;

    const html5QrCode = new Html5QrcodeScanner('temp', {}, false);

    html5QrCode.scanFile(file, true)
      .then(decodedText => {
        handleScanSuccess(decodedText);
      })
      .catch(err => {
        console.error('File scan error:', err);
        toast.error('Could not read QR code from image');
      });
  };

  const handleSendMoney = () => {
    if (scannedData?.userId) {
      // Navigate to send money page with pre-filled recipient
      navigate('/send-money', { 
        state: { 
          recipientId: scannedData.userId,
          recipientData: scannedData 
        } 
      });
    }
  };

  const renderScannedData = () => {
    if (!scannedData) return null;

    return (
      <div className="card">
        <div className="text-center mb-6">
          <div className="inline-flex items-center justify-center w-16 h-16 bg-green-100 rounded-full mb-4">
            <svg className="w-8 h-8 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
            </svg>
          </div>
          <h3 className="text-lg font-semibold text-gray-900">QR Code Scanned!</h3>
          <p className="text-gray-600">Ready to send money</p>
        </div>

        <div className="space-y-4">
          <div className="p-4 bg-gray-50 rounded-lg">
            <h4 className="font-medium text-gray-900 mb-2">Recipient Details:</h4>
            <div className="space-y-2 text-sm">
              <div className="flex justify-between">
                <span className="text-gray-600">Type:</span>
                <span className="text-gray-900">{scannedData.type}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-gray-600">User ID:</span>
                <span className="text-gray-900 font-mono">{scannedData.userId}</span>
              </div>
              {scannedData.name && (
                <div className="flex justify-between">
                  <span className="text-gray-600">Name:</span>
                  <span className="text-gray-900">{scannedData.name}</span>
                </div>
              )}
              {scannedData.email && (
                <div className="flex justify-between">
                  <span className="text-gray-600">Email:</span>
                  <span className="text-gray-900">{scannedData.email}</span>
                </div>
              )}
              {scannedData.amount && (
                <div className="flex justify-between">
                  <span className="text-gray-600">Amount:</span>
                  <span className="text-gray-900 font-semibold">₹{scannedData.amount}</span>
                </div>
              )}
            </div>
          </div>

          <div className="flex space-x-4">
            <button
              onClick={() => {
                setScannedData(null);
                setError(null);
              }}
              className="flex-1 btn-secondary"
            >
              Scan Another
            </button>
            <button
              onClick={handleSendMoney}
              className="flex-1 btn-primary"
            >
              Send Money
            </button>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="max-w-2xl mx-auto">
      <div className="mb-6">
        <button
          onClick={() => navigate('/')}
          className="flex items-center text-gray-600 hover:text-gray-900 mb-4"
        >
          <FiArrowLeft className="h-5 w-5 mr-2" />
          Back to Dashboard
        </button>
        <h1 className="text-2xl font-bold text-gray-900">Scan QR Code</h1>
        <p className="text-gray-600">Scan a QR code to send money quickly</p>
      </div>

      {scannedData ? (
        renderScannedData()
      ) : (
        <div className="space-y-6">
          {/* Scanner Interface */}
          <div className="card">
            {!isScanning ? (
              <div className="text-center py-12">
                <div className="inline-flex items-center justify-center w-16 h-16 bg-primary-100 rounded-full mb-4">
                  <FiCamera className="w-8 h-8 text-primary-600" />
                </div>
                <h3 className="text-lg font-semibold text-gray-900 mb-2">Ready to Scan</h3>
                <p className="text-gray-600 mb-6">
                  Position the QR code within the camera frame to scan
                </p>
                <button
                  onClick={startScanning}
                  className="btn-primary"
                >
                  Start Camera
                </button>
              </div>
            ) : (
              <div>
                <div className="flex items-center justify-between mb-4">
                  <h3 className="text-lg font-semibold text-gray-900">Scanning...</h3>
                  <button
                    onClick={stopScanning}
                    className="text-red-600 hover:text-red-700 font-medium"
                  >
                    Stop
                  </button>
                </div>
                <div id="qr-reader" className="w-full"></div>
              </div>
            )}

            {error && (
              <div className="mt-4 p-4 bg-red-50 border border-red-200 rounded-lg">
                <p className="text-red-800 text-sm">{error}</p>
              </div>
            )}
          </div>

          {/* Alternative Upload Option */}
          <div className="card">
            <div className="text-center">
              <div className="inline-flex items-center justify-center w-12 h-12 bg-gray-100 rounded-full mb-4">
                <FiUpload className="w-6 h-6 text-gray-600" />
              </div>
              <h3 className="text-lg font-semibold text-gray-900 mb-2">Upload QR Image</h3>
              <p className="text-gray-600 mb-4">
                Can't use camera? Upload a QR code image instead
              </p>
              <label className="btn-outline cursor-pointer">
                Choose Image
                <input
                  type="file"
                  accept="image/*"
                  onChange={handleFileUpload}
                  className="hidden"
                />
              </label>
            </div>
          </div>

          {/* Instructions */}
          <div className="card bg-blue-50 border-blue-200">
            <h3 className="text-lg font-semibold text-blue-900 mb-4">How to Scan QR Codes</h3>
            <ul className="space-y-2 text-blue-800">
              <li className="flex items-start">
                <span className="flex-shrink-0 w-6 h-6 bg-blue-200 rounded-full flex items-center justify-center text-xs font-semibold mr-3 mt-0.5">1</span>
                <span>Click "Start Camera" to activate your device's camera</span>
              </li>
              <li className="flex items-start">
                <span className="flex-shrink-0 w-6 h-6 bg-blue-200 rounded-full flex items-center justify-center text-xs font-semibold mr-3 mt-0.5">2</span>
                <span>Point your camera at the QR code</span>
              </li>
              <li className="flex items-start">
                <span className="flex-shrink-0 w-6 h-6 bg-blue-200 rounded-full flex items-center justify-center text-xs font-semibold mr-3 mt-0.5">3</span>
                <span>Wait for the code to be automatically detected</span>
              </li>
              <li className="flex items-start">
                <span className="flex-shrink-0 w-6 h-6 bg-blue-200 rounded-full flex items-center justify-center text-xs font-semibold mr-3 mt-0.5">4</span>
                <span>Review the details and proceed with the payment</span>
              </li>
            </ul>
          </div>
        </div>
      )}
    </div>
  );
};

export default ScanQR;
